using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using LeigodGuard;
class DiscoveryTests {
 static int count;
 static void Check(bool condition,string name){if(!condition)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);count++;}
 static void Var(List<byte> bytes,ulong value){do{byte b=(byte)(value&127);value>>=7;if(value>0)b|=128;bytes.Add(b);}while(value>0);}
 static void Text(List<byte> bytes,string value,bool unicode=false){bytes.Add((byte)(unicode?'c':'"'));var raw=(unicode?Encoding.Unicode:Encoding.UTF8).GetBytes(value);Var(bytes,(ulong)raw.Length);bytes.AddRange(raw);}
 static byte[] Metadata(){var b=new List<byte>();b.Add((byte)'o');Text(b,"id");b.Add((byte)'I');Var(b,42);Text(b,"title");Text(b,"自动测试游戏",true);Text(b,"game_process");Text(b,"Game.exe;CrashReport.exe");Text(b,"client_launch_config_v11");b.Add((byte)'o');Text(b,"Steam");Text(b,"steam://rungameid/123");b.Add((byte)'{');Var(b,1);Text(b,"game_title_en");Text(b,"Automatic Test Game");b.Add((byte)'{');Var(b,5);return b.ToArray();}
 static byte[] Block(byte[] value){var b=new List<byte>();Var(b,0);Var(b,1);Var(b,(ulong)value.Length);b.Add((byte)'k');b.AddRange(value);b.AddRange(BitConverter.GetBytes(0));b.AddRange(BitConverter.GetBytes(1));return b.ToArray();}
 static byte[] Table(byte[] value){var data=Block(value);var all=new List<byte>(data);all.AddRange(new byte[5]);var handle=new List<byte>();Var(handle,0);Var(handle,(ulong)data.Length);var index=Block(handle.ToArray());int indexOffset=all.Count;all.AddRange(index);all.AddRange(new byte[5]);var footer=new List<byte>();Var(footer,0);Var(footer,0);Var(footer,(ulong)indexOffset);Var(footer,(ulong)index.Length);while(footer.Count<40)footer.Add(0);footer.AddRange(BitConverter.GetBytes(0xdb4775248b80fb57UL));all.AddRange(footer);return all.ToArray();}
 static void Main(string[] args){
  if(args.Contains("--local")){var found=Discovery.Scan();Console.WriteLine("LOCAL: installed="+found.InstalledSteamGames+" metadata="+found.LocalMappings+" bindings="+found.Games.Count);foreach(var g in found.Games)Console.WriteLine(g.Name+" | Steam "+g.SteamAppId+" | "+string.Join(",",g.Processes));return;}
  var folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"discovery-fixture");Directory.CreateDirectory(folder);string steam=Path.Combine(folder,"Steam"),library=Path.Combine(folder,"Library");Directory.CreateDirectory(Path.Combine(steam,"steamapps"));var common=Path.Combine(library,"steamapps","common","Test Game");Directory.CreateDirectory(common);
  File.WriteAllText(Path.Combine(steam,"steamapps","libraryfolders.vdf"),"// comment\n\"libraryfolders\" { \"1\" { \"path\" \""+library.Replace("\\","\\\\")+"\" } }");File.WriteAllText(Path.Combine(library,"steamapps","appmanifest_123.acf"),"\"AppState\" { \"appid\" \"123\" \"name\" \"Automatic Test Game\" \"installdir\" \"Test Game\" }");var cache=Path.Combine(folder,"Cache");Directory.CreateDirectory(cache);File.WriteAllBytes(Path.Combine(cache,"000001.log"),Metadata());File.WriteAllBytes(Path.Combine(cache,"000002.ldb"),Table(Metadata()));
  var metadata=Discovery.ParseMetadata(Metadata());Check(metadata.Count==1&&metadata[0].Name=="自动测试游戏"&&metadata[0].SteamId=="123","read Chinese title and Steam id from local serialized game metadata");Check(metadata[0].Processes.SequenceEqual(new[]{"Game.exe"}),"exclude crash reporter from supplied game executables");
  Check(LocalBlocks.Values(Path.Combine(cache,"000002.ldb")).SelectMany(Discovery.ParseMetadata).Any(g=>g.SteamId=="123"),"read metadata from a compacted LevelDB table");Check(Encoding.ASCII.GetString(LocalBlocks.Unsnappy(new byte[]{8,4,97,98,22,2,0}))=="abababab","decode compressed table payload including overlapping copies");bool invalid=false;try{LocalBlocks.Unsnappy(new byte[]{8,22,2,0});}catch{invalid=true;}Check(invalid,"reject corrupt compressed cache payload");
  var foundGame=Discovery.Scan(new[]{steam},new[]{cache});Check(foundGame.Games.Count==1&&foundGame.Games[0].Name=="自动测试游戏"&&foundGame.Games[0].InstallDirectory==common,"combine Steam secondary library with local Chinese game mapping");var game=foundGame.Games[0];Check(game.MatchesExecutable(Path.Combine(common,"bin","Game.exe"),false),"match game executable inside its installation directory");Check(!game.MatchesExecutable(Path.Combine(common+"-other","Game.exe"),true),"do not match directory with similar prefix");Check(!game.MatchesExecutable(Path.Combine(common,"CrashReport.exe"),true)&&!game.MatchesExecutable(Path.Combine(common,"Launcher.exe"),true),"do not count background helper or launcher as game");Check(!game.MatchesExecutable(Path.Combine(folder,"Game.exe"),true),"same executable name outside game directory is not a match");
  var settings=new Settings();Check(Discovery.Merge(settings,foundGame)&&settings.Games.Count==1,"automatically add identified local game without process configuration");Check(!Discovery.Merge(settings,foundGame)&&settings.Games.Count==1,"repeated discovery is idempotent");settings.Games[0].Enabled=false;Discovery.Merge(settings,foundGame);Check(!settings.Games[0].Enabled,"discovery preserves disabled games");settings.Games.Clear();settings.IgnoredGames=new[]{game.DiscoveryKey};Check(!Discovery.Merge(settings,foundGame)&&settings.Games.Count==0,"removed automatic game is not silently added again");
  var manual=new TestSettings();var existing=manual.Games[0];var dota=new DiscoveryResult{Games=new List<GameBinding>{new GameBinding{Name="Dota 2",Aliases=new[]{"DOTA2","Dota 2"},Processes=new[]{"dota2.exe"},Enabled=true,AutoDiscovered=true,SteamAppId="570",InstallDirectory=common}}};Discovery.Merge(manual,dota);Check(manual.Games.Count==1&&!existing.AutoDiscovered&&existing.ProcessKeys[0]=="dota2.exe","upgrade preserves existing manual monitor semantics");
  game.Enabled=true;var m=new MonitorState{Delay=0};var cfg=new Settings{Games=new List<GameBinding>{game}};cfg.Validate();m.Observe(new Frame{Window=1,PauseButton=new TextLine{Text="暂停时长"},ActiveRows=new List<string>{"自动测试游戏 加速中"}},cfg);Check(!m.Tick(new HashSet<string>(game.ProcessKeys,StringComparer.OrdinalIgnoreCase),1)&&m.Current.Seen.Count==1,"automatic path binding tracks running game");Check(m.Tick(new HashSet<string>(),2)&&!m.CanConfirm(m.Current.Id,new HashSet<string>(game.ProcessKeys)),"automatic path binding prompts on exit and rechecks restart");
  var ownFile=System.Reflection.Assembly.GetExecutingAssembly().Location;var ownBinding=new GameBinding{Name="Own test process",Aliases=new[]{"Own test process"},Processes=new[]{Path.GetFileName(ownFile)},Enabled=true,AutoDiscovered=true,ExecutablePath=ownFile};Check(Store.Processes(new[]{ownBinding}).Contains(ownBinding.ProcessKeys[0]),"native process snapshot produces path-specific game marker for this test process");
  var distinct=new Settings{Games=new List<GameBinding>{new GameBinding{Name="Variant",Aliases=new[]{"Variant"},Processes=new string[0],AutoDiscovered=true,InstallDirectory=common,SteamAppId="124",Enabled=true}}};Discovery.Merge(distinct,new DiscoveryResult{Games=new List<GameBinding>{new GameBinding{Name="Variant",Aliases=new[]{"Variant"},Processes=new string[0],AutoDiscovered=true,InstallDirectory=common,SteamAppId="125",Enabled=true}}});Check(distinct.Games.Count==2,"games sharing a title but having different Steam ids remain distinct");
  var manualPath=new GameBinding{Name="自动测试游戏",Aliases=new[]{"自动测试游戏"},Processes=new[]{"Game.exe"},AutoDiscovered=true,ManualAdded=true,ExecutablePath=Path.Combine(common,"Game.exe"),Enabled=true};var manualKey=manualPath.ProcessKeys[0];Discovery.Merge(new Settings{Games=new List<GameBinding>{manualPath}},foundGame);Check(manualPath.ExecutablePath==Path.Combine(common,"Game.exe")&&manualPath.InstallDirectory==null,"automatic discovery preserves explicit executable chosen by user");Check(manualPath.ProcessKeys[0]==manualKey,"learning Steam id never changes an explicit executable monitor key");
  var expanding=new TestSettings();var expandingState=new MonitorState{Delay=0};var active=new Frame{Window=1,PauseButton=new TextLine{Text="暂停时长"},ActiveRows=new List<string>{"DOTA2 加速中","自动测试游戏 加速中"}};expandingState.Observe(active,expanding);expandingState.Tick(new HashSet<string>(new[]{"dota2.exe"},StringComparer.OrdinalIgnoreCase),1);expandingState.Tick(new HashSet<string>(),2);expanding.Games.Add(game);expandingState.Observe(active,expanding);Check(expandingState.Current.Seen.Contains("DOTA2")&&expandingState.Tick(new HashSet<string>(),3),"auto-adding unknown accelerated game preserves already observed exit of unchanged game");
  Console.WriteLine("DISCOVERY TOTAL: "+count+" passed");
 }
}
